pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(uint256 warpTo, address actor, uint256 unlockTime) public {
        warpTo = bound(warpTo, 1, type(uint256).max / 2);
        unlockTime = bound(unlockTime, 0, type(uint256).max / 2);
        vm.warp(warpTo);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 1 ether}(unlockTime);
        (uint256 unlock, ) = c.Acc(actor);
        assertTrue(unlock >= block.timestamp);
    }
}
